window.QUESTIONS = window.QUESTIONS || [];

/* Compact authoring helper: options are plain strings and become A-D. The keyed
   answer is written first for review, then a deterministic rotation (seeded by
   the item id) moves it, so the live bank never leaks the answer position.
   Explanations cite option letters, so those references are remapped as well.
   extra can carry { diagram: 'key' } or { case: 'case-id' }. */
window.Q = function (id, domain, topic, stem, options, answers, explanation, source, extra) {
  var letters = ['A', 'B', 'C', 'D', 'E'];

  // Seeded Fisher-Yates: an item always keeps the same option order.
  var seed = (id * 40503 + 12345) >>> 0;
  function nextRandom() {
    seed = (seed + 0x6D2B79F5) | 0;
    var t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }
  var order = options.map(function (_, i) { return i; });
  for (var j = order.length - 1; j > 0; j--) {
    var swap = Math.floor(nextRandom() * (j + 1));
    var hold = order[j];
    order[j] = order[swap];
    order[swap] = hold;
  }

  var map = {};
  var rotated = order.map(function (oldIndex, newIndex) {
    map[letters[oldIndex]] = letters[newIndex];
    return { letter: letters[newIndex], text: options[oldIndex] };
  });

  var q = {
    id: id,
    domain: domain,
    topic: topic,
    stem: stem,
    options: rotated,
    answers: answers.map(function (a) { return map[a]; }).sort(),
    explanation: explanation.replace(/\*\*([A-E])\*\*/g, function (match, letter) {
      return '**' + (map[letter] || letter) + '**';
    }),
    source: source
  };
  if (extra) { for (var k in extra) { if (Object.prototype.hasOwnProperty.call(extra, k)) q[k] = extra[k]; } }
  return q;
};

